@Composable
private fun ReaderTopBar(
    request: ChimahonReaderRequest,
    currentPage: Int,
    pageCount: Int,
    canvas: ReaderCanvas = ReaderCanvas.Black,
    showTitle: Boolean = true,
    bookmarked: Boolean,
    bookmarkBusy: Boolean,
    onBack: () -> Unit,
    onToggleHud: () -> Unit = {},
    onToggleBookmark: (() -> Unit)?,
    downloadBusy: Boolean = false,
    onDownloadChapter: (() -> Unit)? = null,
    readBusy: Boolean = false,
    onMarkChapterRead: (() -> Unit)? = null,
    onOpenChapterUrl: (() -> Unit)? = null,
    onShareChapter: (() -> Unit)? = null,
) {
    val hudBackground = readerHudBackground(canvas)
    val hudContent = readerHudContent(canvas)
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(52.dp)
            .background(hudBackground.copy(alpha = 0.96f))
            .border(1.dp, hudContent.copy(alpha = 0.08f))
            .clickable(role = Role.Button, onClick = onToggleHud)
            .padding(start = 2.dp, end = 6.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        ReaderAction(
            icon = UiIcon.Back,
            contentDescription = "Back",
            tint = hudContent,
            onClick = onBack,
        )
        Column(
            modifier = Modifier
                .weight(1f)
                .padding(start = 1.dp, end = 5.dp),
        ) {
            if (showTitle) {
                Label(
                    text = request.mangaTitle,
                    color = hudContent,
                    size = 13,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
            }
            Row(
                modifier = Modifier.padding(top = if (showTitle) 2.dp else 0.dp),
                horizontalArrangement = Arrangement.spacedBy(5.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Label(
                    text = request.chapterName,
                    color = hudContent.copy(alpha = 0.70f),
                    size = if (showTitle) 10 else 13,
                    weight = if (showTitle) FontWeight.Normal else FontWeight.SemiBold,
                    maxLines = 1,
                    modifier = Modifier.weight(1f, fill = false),
                )
                ReaderTinyHudPill(
                    text = request.readerChapterMarker(),
                    canvas = canvas,
                )
                request.scanlator?.takeIf { it.isNotBlank() }?.let { scanlator ->
                    ReaderTinyHudPill(
                        text = scanlator,
                        canvas = canvas,
                        subdued = true,
                    )
                }
            }
        }
        if (pageCount > 0) {
            ReaderTinyHudPill(
                text = "$currentPage/$pageCount",
                canvas = canvas,
                modifier = Modifier.padding(horizontal = 2.dp),
            )
        }
        onDownloadChapter?.let {
            ReaderAction(
                icon = UiIcon.Download,
                contentDescription = "Download chapter",
                active = downloadBusy,
                enabled = !downloadBusy,
                tint = hudContent,
                onClick = it,
            )
        }
        onMarkChapterRead?.let {
            ReaderAction(
                icon = UiIcon.DoneAll,
                contentDescription = "Mark chapter read",
                active = readBusy,
                enabled = !readBusy,
                tint = hudContent,
                onClick = it,
            )
        }
        onOpenChapterUrl?.let {
            ReaderAction(
                icon = UiIcon.Web,
                contentDescription = "Open in WebView",
                tint = hudContent,
                onClick = it,
            )
        }
        onShareChapter?.let {
            ReaderAction(
                icon = UiIcon.Share,
                contentDescription = "Share chapter",
                tint = hudContent,
                onClick = it,
            )
        }
        onToggleBookmark?.let {
            ReaderAction(
                icon = if (bookmarked) UiIcon.Bookmark else UiIcon.BookmarkBorder,
                contentDescription = if (bookmarked) "Unbookmark chapter" else "Bookmark chapter",
                active = bookmarked || bookmarkBusy,
                enabled = !bookmarkBusy,
                tint = hudContent,
                onClick = it,
            )
        }
    }
}

@Composable
private fun ReaderTinyHudPill(
    text: String,
    canvas: ReaderCanvas,
    modifier: Modifier = Modifier,
    subdued: Boolean = false,
) {
    Label(
        text = text,
        color = readerHudContent(canvas).copy(alpha = if (subdued) 0.66f else 0.84f),
        size = 8,
        weight = FontWeight.SemiBold,
        maxLines = 1,
        modifier = modifier
            .clip(RoundedCornerShape(50))
            .background(readerHudContent(canvas).copy(alpha = if (subdued) 0.08f else 0.12f))
            .padding(horizontal = 5.dp, vertical = 2.dp),
    )
}

@Composable
private fun HomeNavigationRail(
    selected: HomeTab,
    state: ChimahonUiState,
    compact: Boolean,
    appIcon: ChimahonAppIcon,
    showBadges: Boolean,
    onSelect: (HomeTab) -> Unit,
) {
    Column(
        modifier = Modifier
            .width(if (compact) 72.dp else 88.dp)
            .fillMaxHeight()
            .background(ChimahonPalette.surface)
            .border(1.dp, ChimahonPalette.divider)
            .padding(vertical = 12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        AppMark(appIcon = appIcon)
        Spacer(Modifier.height(if (compact) 12.dp else 20.dp))
        HomeTab.entries.forEach { tab ->
            RailItem(
                tab = tab,
                selected = tab == selected,
                badge = if (showBadges) state.badgeFor(tab) else null,
                compact = compact,
                onClick = { onSelect(tab) },
            )
        }
    }
}

@Composable
private fun RailItem(
    tab: HomeTab,
    selected: Boolean,
    badge: Int?,
    compact: Boolean,
    onClick: () -> Unit,
) {
    Column(
        modifier = Modifier
            .width(if (compact) 62.dp else 76.dp)
            .semantics(mergeDescendants = true) {
                contentDescription = tab.title
                this.selected = selected
                stateDescription = if (selected) "Selected" else "Not selected"
            }
            .clickable(role = Role.Tab, onClick = onClick)
            .padding(vertical = if (compact) 7.dp else 10.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        NavIcon(
            icon = tab.icon,
            contentDescription = tab.title,
            selected = selected,
            badge = badge,
        )
        Label(
            text = tab.title,
            color = if (selected) ChimahonPalette.primary else ChimahonPalette.secondaryText,
            size = if (compact) 9 else 11,
            weight = if (selected) FontWeight.SemiBold else FontWeight.Normal,
            maxLines = 1,
            modifier = Modifier.padding(top = if (compact) 3.dp else 4.dp),
        )
    }
}

@Composable
private fun HomeNavigationBar(
    selected: HomeTab,
    state: ChimahonUiState,
    compact: Boolean,
    showLabels: Boolean,
    showBadges: Boolean,
    onSelect: (HomeTab) -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(
                when {
                    !showLabels -> 58.dp
                    compact -> 62.dp
                    else -> 74.dp
                },
            )
            .background(ChimahonPalette.surface)
            .border(1.dp, ChimahonPalette.divider)
            .padding(horizontal = 8.dp, vertical = 6.dp),
        horizontalArrangement = Arrangement.SpaceEvenly,
    ) {
        HomeTab.entries.forEach { tab ->
            val selectedTab = tab == selected
            Column(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxHeight()
                    .clip(RoundedCornerShape(20.dp))
                    .semantics(mergeDescendants = true) {
                        contentDescription = tab.title
                        this.selected = selectedTab
                        stateDescription = if (selectedTab) "Selected" else "Not selected"
                    }
                    .clickable(role = Role.Tab, onClick = { onSelect(tab) })
                    .padding(vertical = if (compact) 3.dp else 5.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                NavIcon(
                    icon = tab.icon,
                    contentDescription = tab.title,
                    selected = selectedTab,
                    badge = if (showBadges) state.badgeFor(tab) else null,
                )
                if (showLabels) {
                    Label(
                        text = tab.title,
                        color = if (selectedTab) ChimahonPalette.primary else ChimahonPalette.secondaryText,
                        size = if (compact) 9 else 10,
                        weight = if (selectedTab) FontWeight.SemiBold else FontWeight.Normal,
                        maxLines = 1,
                        modifier = Modifier.padding(top = 3.dp),
                    )
                }
            }
        }
    }
}

@Composable
private fun NavIcon(
    icon: UiIcon,
    contentDescription: String,
    selected: Boolean,
    badge: Int?,
) {
    Box(
        modifier = Modifier.size(width = 58.dp, height = 34.dp),
        contentAlignment = Alignment.Center,
    ) {
        Box(
            modifier = Modifier
                .width(if (selected) 56.dp else 44.dp)
                .height(32.dp)
                .clip(RoundedCornerShape(20.dp))
                .background(if (selected) ChimahonPalette.primaryContainer.copy(alpha = 0.96f) else Color.Transparent)
                .border(
                    1.dp,
                    if (selected) ChimahonPalette.primary.copy(alpha = 0.12f) else Color.Transparent,
                    RoundedCornerShape(20.dp),
                ),
            contentAlignment = Alignment.Center,
        ) {
            IconGlyph(
                icon = icon,
                contentDescription = contentDescription,
                tint = if (selected) ChimahonPalette.onPrimaryContainer else ChimahonPalette.secondaryText,
                modifier = Modifier.size(if (selected) 24.dp else 23.dp),
            )
        }
        if (badge != null && badge > 0) {
            val badgeLabel = if (badge > 99) "99+" else badge.toString()
            Box(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .height(17.dp)
                    .widthIn(min = 17.dp)
                    .clip(CircleShape)
                    .background(ChimahonPalette.error)
                    .padding(horizontal = 4.dp),
                contentAlignment = Alignment.Center,
            ) {
                Label(
                    text = badgeLabel,
                    color = Color.White,
                    size = 8,
                    weight = FontWeight.Bold,
                    maxLines = 1,
                )
            }
        }
    }
}

