) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 4.dp)
            .height(44.dp)
            .clip(RoundedCornerShape(8.dp))
            .background(ChimahonPalette.surface)
            .border(1.dp, ChimahonPalette.divider, RoundedCornerShape(8.dp))
            .padding(horizontal = 12.dp),
