    mode: ReaderMode,
    scale: ReaderScale,
    canvas: ReaderCanvas,
    settings: ChimahonReaderSettings,
    onModeChange: (ReaderMode) -> Unit,
    onScaleChange: (ReaderScale) -> Unit,
    onCanvasChange: (ReaderCanvas) -> Unit,
    onSettingsChange: (ChimahonReaderSettings) -> Unit,
    modifier: Modifier = Modifier,
