    ReaderBottomButtonOption("wb", "Open in WebView", aliases = setOf("source")),
    ReaderBottomButtonOption("br", "Open in browser", aliases = setOf("browser")),
    ReaderBottomButtonOption("sh", "Share", aliases = setOf("share")),
