        chapterNumber > 0.0 -> "Ch. ${chapterNumber.toDisplayChapter()}"
        chapterIndex >= 0 && chapterQueue.isNotEmpty() -> "${chapterIndex + 1}/${chapterQueue.size}"
        else -> "Chapter"
    }
}

