private fun Double.toCleanDecimal(): String {
    val rounded = kotlin.math.round(this * 100.0) / 100.0
    return if (rounded.rem(1.0) == 0.0) {
        rounded.toInt().toString()
    } else {
        rounded.toString()
    }
}

