    }
}

@Composable
private fun ReaderPageStepControls(
    currentPage: Int,
    pageCount: Int,
    canvas: ReaderCanvas,
    showPercentage: Boolean,
    showFirstLast: Boolean,
    onPreviousPage: () -> Unit,
    onNextPage: () -> Unit,
    onPageSelected: (Int) -> Unit,
) {
    val pageLabel = if (showPercentage) {
        "$currentPage / $pageCount - ${readerProgressText(currentPage, pageCount)}"
    } else {
        "$currentPage / $pageCount"
    }
    Row(
        modifier = Modifier
            .height(44.dp)
            .clip(RoundedCornerShape(22.dp))
            .background(readerHudContent(canvas).copy(alpha = 0.08f))
            .border(1.dp, readerHudContent(canvas).copy(alpha = 0.06f), RoundedCornerShape(22.dp))
            .padding(horizontal = 2.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(2.dp),
    ) {
        if (showFirstLast) {
            ReaderAction(
                icon = UiIcon.SkipPrevious,
                contentDescription = "First page",
                enabled = currentPage > 1,
                tint = readerHudContent(canvas),
                onClick = { onPageSelected(0) },
            )
        }
        ReaderAction(
            icon = UiIcon.Back,
            contentDescription = "Previous page",
            tint = readerHudContent(canvas),
            onClick = onPreviousPage,
        )
        Box(
            modifier = Modifier.widthIn(min = if (showFirstLast) 94.dp else 58.dp),
            contentAlignment = Alignment.Center,
        ) {
            Label(
                text = pageLabel,
                color = readerHudContent(canvas).copy(alpha = 0.76f),
                size = 11,
                weight = FontWeight.SemiBold,
                maxLines = 1,
            )
        }
        ReaderAction(
            icon = UiIcon.Forward,
            contentDescription = "Next page",
            tint = readerHudContent(canvas),
            onClick = onNextPage,
        )
        if (showFirstLast) {
            ReaderAction(
                icon = UiIcon.SkipNext,
                contentDescription = "Last page",
                enabled = currentPage < pageCount,
                tint = readerHudContent(canvas),
                onClick = { onPageSelected(pageCount - 1) },
            )
        }
    }
}

@Composable
private fun ReaderControlBar(
    mode: ReaderMode,
    canvas: ReaderCanvas,
    currentPage: Int,
    pageCount: Int,
    settingsVisible: Boolean,
    chaptersVisible: Boolean,
    statsVisible: Boolean,
    showPageStrip: Boolean,
    wideLayout: Boolean,
    bottomButtons: List<String>,
    cropActive: Boolean,
    orientation: ChimahonReaderOrientation,
    dualPageMode: ChimahonDualPageMode,
    invertDoublePages: Boolean,
    showPercentage: Boolean,
    onOpenChapterUrl: (() -> Unit)?,
    onShareChapter: (() -> Unit)?,
    onCycleMode: () -> Unit,
    onCycleOrientation: () -> Unit,
    onCyclePageLayout: () -> Unit,
    onShiftDoublePages: () -> Unit,
    onToggleSettings: () -> Unit,
    onToggleChapters: () -> Unit,
    onToggleStats: () -> Unit,
    onToggleCrop: () -> Unit,
    onPreviousPage: () -> Unit,
    onNextPage: () -> Unit,
    onPageSelected: (Int) -> Unit,
) {
    val actionTint = readerHudContent(canvas)
    val showInlinePageControls = pageCount > 0 && (!showPageStrip || wideLayout)
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(64.dp)
            .background(readerHudBackground(canvas).copy(alpha = 0.97f))
            .border(1.dp, readerHudContent(canvas).copy(alpha = 0.08f))
            .padding(horizontal = 8.dp, vertical = 6.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (showInlinePageControls) {
            ReaderPageStepControls(
                currentPage = currentPage,
                pageCount = pageCount,
                canvas = canvas,
                showPercentage = showPercentage,
                showFirstLast = wideLayout,
                onPreviousPage = onPreviousPage,
                onNextPage = onNextPage,
                onPageSelected = onPageSelected,
            )
        }
        Row(
            modifier = Modifier
                .weight(1f)
                .padding(start = if (showInlinePageControls) 8.dp else 0.dp),
            horizontalArrangement = Arrangement.SpaceEvenly,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            if (bottomButtons.readerButtonEnabled("vc", "chapters")) {
                ReaderAction(
                    icon = UiIcon.Chapters,
                    contentDescription = "Chapters",
                    active = chaptersVisible,
                    tint = actionTint,
                    onClick = onToggleChapters,
                )
            }
            if (bottomButtons.readerButtonEnabled("wb", "source")) onOpenChapterUrl?.let {
                ReaderAction(
                    icon = UiIcon.Web,
                    contentDescription = "Open in WebView",
                    tint = actionTint,
                    onClick = it,
                )
            }
            if (bottomButtons.readerButtonEnabled("br", "browser")) onOpenChapterUrl?.let {
                ReaderAction(
                    icon = UiIcon.Browse,
                    contentDescription = "Open in browser",
                    tint = actionTint,
                    onClick = it,
                )
            }
            if (bottomButtons.readerButtonEnabled("sh", "share")) onShareChapter?.let {
                ReaderAction(
                    icon = UiIcon.Share,
                    contentDescription = "Share chapter",
                    tint = actionTint,
                    onClick = it,
                )
            }
            if (bottomButtons.readerButtonEnabled("rm", "mode")) {
                ReaderAction(
                    icon = UiIcon.Swap,
                    contentDescription = "Reading mode: ${mode.title}",
                    tint = actionTint,
                    onClick = onCycleMode,
                )
            }
            if (bottomButtons.readerButtonEnabled("rot", "rotation")) {
                ReaderAction(
                    icon = UiIcon.Rotation,
                    contentDescription = "Orientation: ${orientation.readerTitle()}",
                    active = orientation != ChimahonReaderOrientation.Free,
                    tint = actionTint,
                    onClick = onCycleOrientation,
                )
            }
            if (bottomButtons.readerButtonEnabled(mode.cropBottomButtonKey(), "crop")) {
                ReaderAction(
                    icon = UiIcon.Crop,
                    contentDescription = "Crop borders",
                    active = cropActive,
                    tint = actionTint,
                    onClick = onToggleCrop,
                )
            }
            if (mode.paged && bottomButtons.readerButtonEnabled("pl", "layout")) {
                ReaderAction(
                    icon = UiIcon.PageLayout,
                    contentDescription = "Page layout: ${dualPageMode.readerTitle()}",
                    active = dualPageMode != ChimahonDualPageMode.Off,
                    tint = actionTint,
                    onClick = onCyclePageLayout,
                )
            }
            if (mode.paged && dualPageMode != ChimahonDualPageMode.Off && bottomButtons.readerButtonEnabled("pl", "layout")) {
                ReaderAction(
                    icon = UiIcon.ShiftPage,
                    contentDescription = if (invertDoublePages) "Shift double pages back" else "Shift double pages",
                    active = invertDoublePages,
                    tint = actionTint,
                    onClick = onShiftDoublePages,
                )
            }
            if (bottomButtons.readerButtonEnabled("ms", "stats")) {
                ReaderAction(
                    icon = UiIcon.Statistics,
                    contentDescription = "Statistics",
                    active = statsVisible,
                    tint = actionTint,
                    onClick = onToggleStats,
                )
            }
            ReaderAction(
                icon = UiIcon.Settings,
                contentDescription = "Reader settings",
                active = settingsVisible,
                tint = actionTint,
                onClick = onToggleSettings,
            )
        }
    }
}

@Composable
private fun ReaderPageImage(
    request: ChimahonReaderRequest,
    page: ChimahonReaderPage,
    paged: Boolean,
    scale: ReaderScale,
    canvas: ReaderCanvas,
    readerSettings: ChimahonReaderSettings,
    cachedState: ReaderPageUiState?,
    onStateChange: (ReaderPageUiState) -> Unit,
    onLoadReaderPageImage: suspend (ChimahonReaderPage) -> ByteArray,
) {
    var retryKey by remember(page) { mutableIntStateOf(0) }
    var pageActionsVisible by remember(page) { mutableStateOf(false) }
    var pageActionBusy by remember(page) { mutableStateOf<String?>(null) }
    var pageActionMessage by remember(page) { mutableStateOf<String?>(null) }
    var panOffset by remember(page, scale, readerSettings.navigateToPan) { mutableStateOf(Offset.Zero) }
    val scope = rememberCoroutineScope()

    LaunchedEffect(page, retryKey) {
        if (retryKey == 0 && cachedState is ReaderPageUiState.Ready) return@LaunchedEffect
        onStateChange(ReaderPageUiState.Loading)
        onStateChange(
            runCatching {
                onLoadReaderPageImage(page).decodeToImageBitmap()
            }.fold(
                onSuccess = ReaderPageUiState::Ready,
                onFailure = { ReaderPageUiState.Failed(it.message ?: "Unable to decode page image.") },
            ),
        )
    }

    Box(
        modifier = if (paged) {
            Modifier
                .fillMaxSize()
                .background(canvas.readerBackground(readerSettings.pureBlackBackground))
                .padding(
                    horizontal = if (readerSettings.cropBorders) 0.dp else readerSettings.horizontalPadding.dp,
                    vertical = if (readerSettings.cropBorders) 0.dp else readerSettings.verticalPadding.dp,
                )
        } else {
            Modifier
                .fillMaxWidth()
                .widthIn(
                    max = when (scale) {
                        ReaderScale.FitScreen -> 900.dp
                        ReaderScale.FitWidth -> 1180.dp
                        ReaderScale.FitHeight -> 760.dp
                    },
                )
                .heightIn(min = 260.dp)
                .background(canvas.readerBackground(readerSettings.pureBlackBackground))
                .padding(
                    horizontal = if (readerSettings.cropBorders) 0.dp else readerSettings.horizontalPadding.dp,
                    vertical = if (readerSettings.cropBorders) 0.dp else readerSettings.verticalPadding.dp,
                )
        },
        contentAlignment = Alignment.Center,
    ) {
        when (val pageState = cachedState ?: ReaderPageUiState.Loading) {
            ReaderPageUiState.Loading -> {
                ReaderPageMessage(
                    marker = (page.index + 1).toString(),
                    title = "Loading page",
                    detail = "Requesting image from the source.",
                )
            }
            is ReaderPageUiState.Failed -> {
                ReaderPageMessage(
                    marker = "!",
                    title = "Page ${page.index + 1} failed",
                    detail = pageState.message,
                    action = "Retry",
                    onAction = { retryKey++ },
                )
            }
            is ReaderPageUiState.Ready -> {
                val aspectRatio = pageState.image.width.toFloat() /
                    pageState.image.height.coerceAtLeast(1).toFloat()
                val colorFilter = readerSettings.readerColorFilter()
                val panEnabled = paged && readerSettings.navigateToPan && scale != ReaderScale.FitScreen
                val baseImageModifier = when {
                        paged && readerSettings.cropBorders -> Modifier.fillMaxSize()
                        paged && scale == ReaderScale.FitScreen -> Modifier.fillMaxSize()
                        paged && scale == ReaderScale.FitHeight -> Modifier
                            .fillMaxHeight()
                            .aspectRatio(aspectRatio)
                        else -> Modifier
                            .fillMaxWidth()
                            .aspectRatio(aspectRatio)
                    }
                val imageModifier = baseImageModifier
                    .graphicsLayer {
                        if (panEnabled) {
                            translationX = panOffset.x
                            translationY = panOffset.y
                        }
                    }
                    .pointerInput(page, panEnabled) {
                        if (panEnabled) {
                            detectDragGestures(
                                onDrag = { change, dragAmount ->
                                    change.consume()
                                    panOffset += dragAmount
                                },
                            )
                        }
                    }
                    .pointerInput(page) {
                        detectTapGestures(
                            onLongPress = {
                                pageActionMessage = null
                                pageActionsVisible = true
                            },
                        )
                    }
                if (paged && readerSettings.splitWidePages && aspectRatio >= 1.25f) {
                    ReaderSplitWidePageImage(
                        bitmap = pageState.image,
                        contentDescription = "Page ${page.index + 1} split spread",
                        rtl = readerSettings.mode == ChimahonReaderMode.RightToLeft,
                        colorFilter = colorFilter,
                        modifier = imageModifier,
                    )
                } else {
                    Image(
                        bitmap = pageState.image,
                        contentDescription = "Page ${page.index + 1}",
                        contentScale = if (readerSettings.cropBorders) ContentScale.Crop else ContentScale.Fit,
                        colorFilter = colorFilter,
                        modifier = imageModifier,
                    )
                }
                readerSettings.readerBrightnessOverlay()?.let { overlay ->
                    Box(
                        modifier = Modifier
                            .matchParentSize()
                            .background(overlay),
                    )
                }
            }
        }
    }
    if (pageActionsVisible) {
        ReaderPageActionsDialog(
            request = request,
            page = page,
            busyAction = pageActionBusy,
            message = pageActionMessage,
            onDismiss = {
                if (pageActionBusy == null) pageActionsVisible = false
            },
            onCopyUrl = {
                pageActionMessage = ChimahonReaderPageActions.copyPageUrlToClipboard(page).message
            },
            onCopyInfo = {
                pageActionMessage = ChimahonReaderPageActions.copyPageTextToClipboard(request, page).message
            },
            onShareInfo = {
                pageActionMessage = ChimahonReaderPageActions.sharePageText(request, page).message
            },
            onResetView = {
                panOffset = Offset.Zero
                pageActionMessage = "Page view reset."
            },
            onSaveImage = {
                if (pageActionBusy == null) {
                    scope.launch {
                        pageActionBusy = "save"
                        pageActionMessage = runCatching {
                            val bytes = onLoadReaderPageImage(page)
                            ChimahonReaderPageActions.savePageBytes(request, page, bytes).message
                        }.getOrElse { it.message ?: "Page image could not be saved." }
                        pageActionBusy = null
                    }
                }
            },
            onShareImage = {
                if (pageActionBusy == null) {
                    scope.launch {
                        pageActionBusy = "share"
                        pageActionMessage = runCatching {
                            val bytes = onLoadReaderPageImage(page)
                            ChimahonReaderPageActions.sharePageBytes(request, page, bytes).message
                        }.getOrElse { it.message ?: "Page image could not be shared." }
                        pageActionBusy = null
                    }
                }
            },
        )
    }
}

@Composable
private fun ReaderSplitWidePageImage(
    bitmap: ImageBitmap,
    contentDescription: String,
    rtl: Boolean,
    colorFilter: ColorFilter?,
    modifier: Modifier = Modifier,
) {
    Canvas(
        modifier = modifier.semantics {
            this.contentDescription = contentDescription
        },
    ) {
        val halfWidth = (bitmap.width / 2).coerceAtLeast(1)
        val leftHalf = 0 to halfWidth
        val rightHalf = halfWidth to (bitmap.width - halfWidth).coerceAtLeast(1)
        val halves = if (rtl) listOf(rightHalf, leftHalf) else listOf(leftHalf, rightHalf)
        val gutter = min(size.width * 0.018f, 16f)
        val panelWidth = ((size.width - gutter) / 2f).coerceAtLeast(1f)

        halves.forEachIndexed { index, (srcX, srcWidth) ->
            val fitScale = min(
                panelWidth / srcWidth.toFloat(),
                size.height / bitmap.height.coerceAtLeast(1).toFloat(),
            )
            val dstWidth = (srcWidth * fitScale).coerceAtLeast(1f)
            val dstHeight = (bitmap.height * fitScale).coerceAtLeast(1f)
            val panelStart = index * (panelWidth + gutter)
            val dstX = panelStart + ((panelWidth - dstWidth) / 2f)
            val dstY = (size.height - dstHeight) / 2f
            drawImage(
                image = bitmap,
                srcOffset = IntOffset(srcX, 0),
                srcSize = IntSize(srcWidth, bitmap.height),
                dstOffset = IntOffset(dstX.roundToInt(), dstY.roundToInt()),
                dstSize = IntSize(dstWidth.roundToInt(), dstHeight.roundToInt()),
                colorFilter = colorFilter,
            )
        }
        drawRect(
            color = Color.Black.copy(alpha = 0.20f),
            topLeft = Offset((size.width - gutter) / 2f, 0f),
            size = Size(gutter, size.height),
        )
    }
}

private fun ChimahonReaderSettings.readerColorFilter(): ColorFilter? {
    if (!colorFilterEnabled) return null
    return when {
        invertColors -> ColorFilter.colorMatrix(
            ColorMatrix(
                floatArrayOf(
                    -1f, 0f, 0f, 0f, 255f,
                    0f, -1f, 0f, 0f, 255f,
                    0f, 0f, -1f, 0f, 255f,
                    0f, 0f, 0f, 1f, 0f,
                ),
            ),
        )
        grayscale -> ColorFilter.colorMatrix(ColorMatrix().apply { setToSaturation(0f) })
        else -> null
    }
}

private fun ChimahonReaderSettings.readerBrightnessOverlay(): Color? {
    if (!colorFilterEnabled || brightness == 0) return null
    val alpha = (kotlin.math.abs(brightness).coerceAtMost(100) / 100f) * 0.42f
    return if (brightness > 0) {
        Color.White.copy(alpha = alpha)
    } else {
        Color.Black.copy(alpha = alpha)
    }
}

@Composable
private fun ReaderPageActionsDialog(
    request: ChimahonReaderRequest,
    page: ChimahonReaderPage,
    busyAction: String?,
    message: String?,
    onDismiss: () -> Unit,
    onSaveImage: () -> Unit,
    onShareImage: () -> Unit,
    onCopyUrl: () -> Unit,
    onCopyInfo: () -> Unit,
    onShareInfo: () -> Unit,
    onResetView: () -> Unit,
) {
    Dialog(onDismissRequest = onDismiss) {
        Column(
            modifier = Modifier
                .widthIn(min = 300.dp, max = 420.dp)
                .clip(RoundedCornerShape(18.dp))
                .background(ReaderPalette.chrome.copy(alpha = 0.99f))
                .border(1.dp, ReaderPalette.divider.copy(alpha = 0.82f), RoundedCornerShape(18.dp))
                .padding(horizontal = 14.dp, vertical = 12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            ReaderSheetDragHandle()
            ReaderSheetHeader(
                title = "Page actions",
                subtitle = "${request.chapterName} - page ${page.index + 1}",
                icon = UiIcon.Info,
            )
            ReaderPageActionRow(
                title = if (busyAction == "save") "Saving image" else "Save image",
                icon = UiIcon.Download,
                active = busyAction == "save",
                enabled = busyAction == null,
                onClick = onSaveImage,
            )
            ReaderPageActionRow(
                title = if (busyAction == "share") "Sharing image" else "Share image",
                icon = UiIcon.Web,
                active = busyAction == "share",
                enabled = busyAction == null,
                onClick = onShareImage,
            )
            ReaderPageActionRow(
                title = "Copy page URL",
                icon = UiIcon.Link,
                enabled = busyAction == null,
                onClick = onCopyUrl,
            )
            ReaderPageActionRow(
                title = "Copy page info",
                icon = UiIcon.Info,
                enabled = busyAction == null,
                onClick = onCopyInfo,
            )
            ReaderPageActionRow(
                title = "Share page info",
                icon = UiIcon.Forward,
                enabled = busyAction == null,
                onClick = onShareInfo,
            )
            ReaderPageActionRow(
                title = "Reset page view",
                icon = UiIcon.Crop,
                enabled = busyAction == null,
                onClick = onResetView,
            )
            message?.let {
                Label(
                    it,
                    if (busyAction == null) ReaderPalette.secondaryText else Color.White,
                    11,
                    lineHeight = 16,
                    maxLines = 3,
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(8.dp))
                        .background(ReaderPalette.control.copy(alpha = 0.32f))
                        .padding(horizontal = 12.dp, vertical = 10.dp),
                )
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.End,
            ) {
                ReaderTextAction(
                    text = "Close",
                    onClick = onDismiss,
                )
            }
        }
    }
}

@Composable
private fun ReaderPageActionRow(
    title: String,
    icon: UiIcon,
    enabled: Boolean,
    modifier: Modifier = Modifier,
    active: Boolean = false,
    onClick: () -> Unit,
) {
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(48.dp)
            .clip(RoundedCornerShape(6.dp))
            .background(if (active) ReaderPalette.selectedControl else ReaderPalette.control.copy(alpha = 0.34f))
            .clickable(enabled = enabled, onClick = onClick)
            .padding(horizontal = 12.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        IconGlyph(
            icon = icon,
            contentDescription = title,
            tint = if (enabled || active) Color.White else ReaderPalette.secondaryText.copy(alpha = 0.45f),
            modifier = Modifier.size(19.dp),
        )
        Label(
            title,
            if (enabled || active) Color.White else ReaderPalette.secondaryText.copy(alpha = 0.45f),
            12,
            weight = FontWeight.SemiBold,
            maxLines = 1,
        )
    }
}

