private data class DownloadQueueSourceGroup(
    val sourceId: Long,
    val sourceName: String,
    val entries: List<ChimahonDownloadQueueEntry>,
)

@Composable
private fun DownloadQueueToolbar(
    queue: ChimahonDownloadQueueData?,
    message: String?,
    processing: Boolean,
    autoRun: Boolean,
    onAutoRunChange: (Boolean) -> Unit,
    onTogglePaused: () -> Unit,
    onProcessNext: () -> Unit,
    onClearCompleted: () -> Unit,
) {
    val entries = queue?.entries.orEmpty()
    val completedCount = entries.count { it.status == ChimahonDownloadState.Downloaded }
    val pausedCount = entries.count { it.status == ChimahonDownloadState.Paused }
    val downloadedBytes = entries.sumOf { it.downloadedBytes }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .padding(horizontal = 16.dp, vertical = 12.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Box(
                modifier = Modifier
                    .size(42.dp)
                    .clip(CircleShape)
                    .background(ChimahonPalette.primaryContainer),
                contentAlignment = Alignment.Center,
            ) {
                IconGlyph(
                    icon = if (queue?.paused == true) UiIcon.Pause else UiIcon.Download,
                    contentDescription = "",
                    tint = ChimahonPalette.primary,
                    modifier = Modifier.size(22.dp),
                )
            }
            Column(
                modifier = Modifier
                    .weight(1f)
                    .padding(horizontal = 12.dp),
            ) {
                Label(
                    if (queue?.paused == true) "Download queue paused" else "Download queue",
                    ChimahonPalette.onSurface,
                    14,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
                Label(
                    if (processing) "Processing the next chapter" else queue?.downloadQueueSummary() ?: "Loading saved queue",
                    ChimahonPalette.secondaryText,
                    11,
                    maxLines = 2,
                    modifier = Modifier.padding(top = 3.dp),
                )
            }
            TextButtonLike(
                text = if (queue?.paused == true) "Resume all" else "Pause all",
                onClick = onTogglePaused,
            )
        }
        if (queue != null && entries.isNotEmpty()) {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    QueueStatChip(
                        "Queued",
                        queue.pendingCount.toString(),
                        UiIcon.Chapters,
                        Modifier.weight(1f),
                    )
                    QueueStatChip(
                        "Active",
                        queue.activeCount.toString(),
                        UiIcon.Play,
                        Modifier.weight(1f),
                        tint = ChimahonDownloadState.Downloading.statusColor(),
                    )
                }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    QueueStatChip(
                        "Paused",
                        pausedCount.toString(),
                        UiIcon.Pause,
                        Modifier.weight(1f),
                        tint = ChimahonDownloadState.Paused.statusColor(),
                    )
                    QueueStatChip(
                        "Done",
                        completedCount.toString(),
                        UiIcon.CheckCircle,
                        Modifier.weight(1f),
                        tint = ChimahonDownloadState.Downloaded.statusColor(),
                    )
                }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    QueueStatChip(
                        "Failed",
                        queue.failedCount.toString(),
                        UiIcon.Info,
                        Modifier.weight(1f),
                        tint = ChimahonDownloadState.Error.statusColor(),
                    )
                    QueueStatChip(
                        "Size",
                        downloadedBytes.toReadableBytes(),
                        UiIcon.Storage,
                        Modifier.weight(1f),
                    )
                }
            }
        }
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Label(
                message ?: if (completedCount > 0) {
                    "$completedCount completed download(s) can be cleared"
                } else {
                    "Per-chapter controls match the Android download queue"
                },
                if (message?.startsWith("Could not") == true) ChimahonPalette.error else ChimahonPalette.secondaryText,
                11,
                maxLines = 2,
                modifier = Modifier.weight(1f),
            )
            if (queue != null && queue.pendingCount > 0 && queue.paused.not()) {
                TextButtonLike(if (processing) "Working" else "Start next", onClick = onProcessNext)
                Spacer(modifier = Modifier.width(8.dp))
            }
            if (queue != null && queue.entries.isNotEmpty()) {
                QueueTextAction(
                    if (autoRun) "Auto on" else "Auto off",
                    onClick = { onAutoRunChange(!autoRun) },
                )
                Spacer(modifier = Modifier.width(8.dp))
            }
            if (completedCount > 0) {
                TextButtonLike("Clear done", onClick = onClearCompleted)
            }
        }
    }
}

@Composable
private fun DownloadQueueSourceHeader(group: DownloadQueueSourceGroup) {
    val active = group.entries.count { it.status == ChimahonDownloadState.Downloading }
    val failed = group.entries.count { it.status == ChimahonDownloadState.Error }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.background)
            .padding(start = 16.dp, end = 16.dp, top = 14.dp, bottom = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        IconGlyph(
            icon = UiIcon.Reorder,
            contentDescription = "",
            tint = ChimahonPalette.secondaryText,
            modifier = Modifier.size(18.dp),
        )
        Label(
            "${group.sourceName} (${group.entries.size})",
            ChimahonPalette.secondaryText,
            11,
            weight = FontWeight.Bold,
            maxLines = 1,
            modifier = Modifier
                .weight(1f)
                .padding(start = 10.dp),
        )
        val status = listOfNotNull(
            active.takeIf { it > 0 }?.let { "$it active" },
            failed.takeIf { it > 0 }?.let { "$it failed" },
        ).joinToString(" - ")
        if (status.isNotBlank()) {
            Label(
                status,
                if (failed > 0) ChimahonPalette.error else ChimahonPalette.primary,
                10,
                weight = FontWeight.SemiBold,
                maxLines = 1,
            )
        }
    }
}

@Composable
private fun QueueStatChip(
    label: String,
    value: String,
    icon: UiIcon,
    modifier: Modifier = Modifier,
    tint: Color = ChimahonPalette.primary,
) {
    Row(
        modifier = modifier
            .height(34.dp)
            .clip(RoundedCornerShape(8.dp))
            .background(ChimahonPalette.background)
            .border(1.dp, ChimahonPalette.divider, RoundedCornerShape(8.dp))
            .padding(horizontal = 9.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(6.dp),
    ) {
