@Composable
private fun SettingsMultiChoiceRow(
    title: String,
    options: List<String>,
    selected: List<String>,
    emptyLabel: String,
    onToggle: (String) -> Unit,
) {
    val selectedLabel = if (selected.isEmpty()) emptyLabel else selected.joinToString()
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .padding(horizontal = 20.dp, vertical = 12.dp),
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Label(
                title,
                ChimahonPalette.onSurface,
                14,
                weight = FontWeight.SemiBold,
                maxLines = 1,
                modifier = Modifier.weight(1f),
            )
            SettingsValuePill(
                selectedLabel,
                active = selected.isNotEmpty(),
                modifier = Modifier
                    .padding(start = 12.dp)
                    .widthIn(max = 160.dp),
            )
        }
        LazyRow(
            modifier = Modifier.padding(top = 9.dp),
            horizontalArrangement = Arrangement.spacedBy(7.dp),
        ) {
            items(options, key = { it }) { option ->
                val active = option in selected
                Box(
                    modifier = Modifier
                        .heightIn(min = 30.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(if (active) ChimahonPalette.primaryContainer.copy(alpha = 0.88f) else ChimahonPalette.surfaceVariant.copy(alpha = 0.72f))
                        .border(
                            1.dp,
                            if (active) ChimahonPalette.primary.copy(alpha = 0.26f) else ChimahonPalette.divider.copy(alpha = 0.64f),
                            RoundedCornerShape(8.dp),
                        )
                        .clickable { onToggle(option) }
                        .padding(horizontal = 10.dp, vertical = 6.dp),
                    contentAlignment = Alignment.Center,
                ) {
                    Label(
                        text = option,
                        color = if (active) ChimahonPalette.primary else ChimahonPalette.secondaryText,
                        size = 11,
                        weight = if (active) FontWeight.SemiBold else FontWeight.Normal,
                        maxLines = 1,
                    )
                }
            }
        }
    }
}

@Composable
private fun ThemePickerRow(
    selected: ChimahonAppTheme,
    dark: Boolean,
    onSelect: (ChimahonAppTheme) -> Unit,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .padding(vertical = 14.dp),
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 20.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Label("App theme", ChimahonPalette.onSurface, 14, weight = FontWeight.SemiBold, maxLines = 1)
                Label(
                    "Match Chimahon color presets",
                    ChimahonPalette.secondaryText,
                    11,
                    maxLines = 1,
                    modifier = Modifier.padding(top = 3.dp),
                )
            }
            SettingsValuePill(selected.title, modifier = Modifier.padding(start = 12.dp))
        }
        LazyRow(
            contentPadding = PaddingValues(horizontal = 20.dp, vertical = 10.dp),
            horizontalArrangement = Arrangement.spacedBy(9.dp),
        ) {
            items(ChimahonAppTheme.entries, key = { it.name }) { theme ->
                val colors = chimahonThemeColors(theme, dark = dark, amoled = false)
                val active = theme == selected
                Column(
                    modifier = Modifier
                        .width(126.dp)
                        .clip(RoundedCornerShape(10.dp))
                        .background(colors.surface)
                        .border(
                            width = if (active) 2.dp else 1.dp,
                            color = if (active) colors.primary else colors.divider,
                            shape = RoundedCornerShape(10.dp),
                        )
                        .clickable { onSelect(theme) }
                        .padding(10.dp),
                ) {
                    Box(modifier = Modifier.fillMaxWidth()) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                        ) {
                            listOf(colors.primary, colors.primaryContainer, colors.surfaceVariant).forEach {
                                Box(
                                    modifier = Modifier
                                        .weight(1f)
                                        .height(18.dp)
                                        .clip(RoundedCornerShape(4.dp))
                                        .background(it),
                                )
                            }
                        }
                        if (active) {
                            Box(
                                modifier = Modifier
                                    .align(Alignment.CenterEnd)
                                    .size(18.dp)
                                    .clip(CircleShape)
                                    .background(colors.primary),
                                contentAlignment = Alignment.Center,
                            ) {
                                IconGlyph(
                                    icon = UiIcon.CheckCircle,
                                    contentDescription = "",
                                    tint = colors.surface,
                                    modifier = Modifier.size(13.dp),
                                )
                            }
                        }
                    }
                    Label(
                        theme.title,
                        colors.onSurface,
                        11,
                        weight = if (active) FontWeight.Bold else FontWeight.SemiBold,
                        maxLines = 2,
                        modifier = Modifier.padding(top = 8.dp),
                    )
                }
            }
        }
    }
}

private fun Long.toReadingDuration(): String {
    if (this <= 0L) return "0m"
    val hours = this / 3_600_000L
    val minutes = (this % 3_600_000L) / 60_000L
    return buildString {
        if (hours > 0L) append(hours).append("h ")
        append(minutes).append("m")
    }.trim()
}

