private fun ChimahonChapterEntry.chapterStateLabel(): String {
    return when {
        read -> "Read"
        lastPageRead > 0L -> "Page ${lastPageRead + 1}"
        bookmarked -> "Bookmarked"
        else -> "Unread"
    }
